-- Weekly Arena 2026-11-09: 10 questions, all unseen.
insert into public.arenas(id,title,description,starts_at,ends_at,duration_minutes,status,questions)
values('41b59a76-590e-4086-8d32-164d1f95f513','Weekly Arena — 2026-11-09','A fresh weekly set of 10 problems across Algebra, Geometry, Combinatorics and Number Theory. Open for 7 days; 60 minutes once you begin.','2026-11-09T00:00:00.000Z','2026-11-16T00:00:00.000Z',60,'published','[{"id":"comb-f01","title":"Digit Sets and Permutations","question":"How many four-digit positive integers have four distinct digits and a digit sum divisible by $9$?","correctAnswer":"516","solution":"The generating polynomial $\\prod_{d=0}^{9}(1+t z^d)$ shows that $24$ four-digit sets have digit sum $0$ modulo $9$: $14$ contain no zero and $10$ contain zero. The first type contributes $14\\cdot4!=336$ numbers; the second contributes $10\\cdot(4!-3!)=180$. The total is $336+180=516$.","hint":"First choose the four-digit set. A set containing $0$ has only $4!-3!$ valid arrangements; a set without $0$ has $4!$.","topic":"Combinatorics","level":"Foundation","competition":"AMC","estimatedSteps":5,"abstraction":4,"type":"text","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"points":73,"difficulty":0.52},{"id":"gen-aime-com-019","title":"Distinct digits, one residue","question":"How many 5-digit integers have distinct digits and are divisible by $3$?","correctAnswer":"9072","solution":"Enumerating residue-compatible digit sets and valid leading digits gives 9072.","hint":"Group digit sets by their sum modulo 3 and handle a leading zero separately.","topic":"Combinatorics","level":"Advanced","competition":"AIME","estimatedSteps":5,"abstraction":4,"type":"text","answerMode":"numeric-grid","answerDigits":4,"maxAttempts":3,"points":73,"difficulty":0.52},{"id":"gen-aime-geo-008","title":"Heron, carefully","question":"A triangle has side lengths 5, 5, 6. Find its area.","correctAnswer":"012","solution":"Heron’s formula gives area 12.","hint":"Use Heron’s formula with the semiperimeter.","topic":"Geometry","level":"Advanced","competition":"AIME","estimatedSteps":3,"abstraction":2,"type":"text","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"points":49,"difficulty":-0.44},{"id":"gen-aime-num-023","title":"Coprime choices","question":"How many positive integers less than 72 are coprime to 72?","correctAnswer":"024","solution":"$\\varphi(72)=24$.","hint":"Use Euler’s product over distinct prime factors.","topic":"Number Theory","level":"Advanced","competition":"AIME","estimatedSteps":3,"abstraction":2,"type":"text","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"points":47,"difficulty":-0.52},{"id":"gen-amc-geo-013","title":"Similarity carries the length","question":"Two equilateral triangles have side ratio $1:4$. If the smaller side is 4, find the larger side.","correctAnswer":"16","solution":"The larger side is 4 times 4, or 16.","hint":"Multiply by the scale factor once.","topic":"Geometry","level":"Foundation","competition":"AMC","estimatedSteps":2,"abstraction":2,"type":"text","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"points":42,"difficulty":-0.72},{"id":"gen-aime-com-016","title":"Binary strings with breathing room","question":"How many binary strings of length 10 contain no two consecutive $1$s?","correctAnswer":"144","solution":"The recurrence $F_n=F_{n-1}+F_{n-2}$ gives 144.","hint":"Split by the first symbol; the recurrence is Fibonacci-like.","topic":"Combinatorics","level":"Advanced","competition":"AIME","estimatedSteps":3,"abstraction":3,"type":"text","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"points":53,"difficulty":-0.28},{"id":"gen-aime-geo-009","title":"A cyclic quadrilateral","question":"A cyclic quadrilateral has sides $2,3,4,5$. Find the square of its area.","correctAnswer":"120","solution":"$K^2=120$.","hint":"Use Brahmagupta’s formula with the semiperimeter.","topic":"Geometry","level":"Advanced","competition":"AIME","estimatedSteps":3,"abstraction":3,"type":"text","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"points":55,"difficulty":-0.2},{"id":"gen-aime-alg-004","title":"A sequence with a footprint","question":"A sequence is defined by $u_n=n^2+2n+2$. Find $u_{12}$.","correctAnswer":"170","solution":"$u_{12}=12^2+2(12)+2=170$.","hint":"Substitute the index and keep the quadratic and linear terms separate.","topic":"Algebra","level":"Advanced","competition":"AIME","estimatedSteps":2,"abstraction":1,"type":"text","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"points":34,"difficulty":-1.04},{"id":"gen-aime-alg-001","title":"A symmetric pair","question":"Positive reals $a,b$ satisfy $a+b=6$ and $ab=5$. Find $a^2+b^2$.","correctAnswer":"026","solution":"$a^2+b^2=6^2-2(5)=26$.","hint":"Expand $(a+b)^2$ and isolate $a^2+b^2$.","topic":"Algebra","level":"Advanced","competition":"AIME","estimatedSteps":2,"abstraction":1,"type":"text","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"points":34,"difficulty":-1.04},{"id":"gen-aime-num-025","title":"A periodic congruence","question":"How many integers $n$ with $1\\le n\\le548$ satisfy $n\\equiv2^n\\pmod7$?","correctAnswer":"078","solution":"The valid residues in one period are 11, 15, and 16; counting them through 548 gives 78.","hint":"The condition repeats with period $\\operatorname{lcm}(7,3)=21$.","topic":"Number Theory","level":"Advanced","competition":"AIME","estimatedSteps":4,"abstraction":4,"type":"text","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"points":66,"difficulty":0.24}]'::jsonb)
on conflict(id) do nothing;
